// Regenerates supabase/seed/0002_seed.sql from data/syllabus.ts and data/glossary.ts.
// Run: npx tsx scripts/make_seed_sql.ts
import { writeFileSync } from "node:fs";
import { EXAMS, partId, unitId } from "../data/syllabus";
import { GLOSSARY } from "../data/glossary";

const q = (s: string | null | undefined) => (s == null ? "null" : `'${String(s).replace(/'/g, "''")}'`);
const arr = (a: string[]) => `array[${a.map(q).join(",")}]::text[]`;
const out: string[] = [
  "-- Generated by scripts/make_seed_sql.ts. Safe to run again (updates in place).",
  "begin;",
];
for (const e of EXAMS) {
  out.push(
    `insert into exams (code,name_ta,total_questions,total_marks,mark_per_q,duration_min,exam_date,notes_ta) values (${q(e.code)},${q(e.name)},${e.totalQuestions},${e.totalMarks},${e.markPerQ},${e.durationMin},${e.examDate ? q(e.examDate) : "null"},${q(e.notes)})
  on conflict (code) do update set name_ta=excluded.name_ta,total_questions=excluded.total_questions,total_marks=excluded.total_marks,mark_per_q=excluded.mark_per_q,duration_min=excluded.duration_min,exam_date=coalesce(exams.exam_date,excluded.exam_date),notes_ta=excluded.notes_ta;`
  );
  e.parts.forEach((p, pi) => {
    const pid = partId(e.code, p.key);
    out.push(
      `insert into parts (id,exam_code,sort,name_ta,questions,gate_min_marks) values (${q(pid)},${q(e.code)},${pi + 1},${q(p.name)},${p.questions},${p.gateMinMarks ?? "null"})
  on conflict (id) do update set sort=excluded.sort,name_ta=excluded.name_ta,questions=excluded.questions,gate_min_marks=excluded.gate_min_marks;`
    );
    p.units.forEach((u, ui) => {
      const uid = unitId(e.code, p.key, u.key);
      out.push(
        `insert into units (id,part_id,exam_code,sort,name_ta,questions,approx,standard,subject,source_subjects) values (${q(uid)},${q(pid)},${q(e.code)},${(pi + 1) * 100 + ui + 1},${q(u.name)},${u.questions},${!!u.approx},${q(p.key === "APT" || p.key === "TAMIL" ? "SSLC" : e.standard)},${q(u.subject)},${arr(u.sources)})
  on conflict (id) do update set sort=excluded.sort,name_ta=excluded.name_ta,questions=excluded.questions,approx=excluded.approx,standard=excluded.standard,subject=excluded.subject,source_subjects=excluded.source_subjects;`
      );
      u.topics.forEach((t, ti) => {
        out.push(
          `insert into topics (unit_id,sort,name_ta) values (${q(uid)},${ti + 1},${q(t)}) on conflict (unit_id,sort) do update set name_ta=excluded.name_ta;`
        );
      });
      out.push(`delete from topics where unit_id=${q(uid)} and sort>${u.topics.length};`);
    });
  });
}
for (const [en, ta, cat] of GLOSSARY) {
  out.push(`insert into glossary (en,ta,category) values (${q(en)},${q(ta)},${q(cat)}) on conflict (en) do update set ta=excluded.ta,category=excluded.category;`);
}
out.push("commit;");
writeFileSync("supabase/seed/0002_seed.sql", out.join("\n") + "\n");
const units = EXAMS.flatMap((e) => e.parts.flatMap((p) => p.units));
console.log(`exams ${EXAMS.length}, units ${units.length}, topics ${units.reduce((s, u) => s + u.topics.length, 0)}, glossary ${GLOSSARY.length}`);
for (const e of EXAMS) {
  const total = e.parts.reduce((s, p) => s + p.questions, 0);
  const unitsTotal = e.parts.reduce((s, p) => s + p.units.reduce((t, u) => t + u.questions, 0), 0);
  for (const p of e.parts) {
    const ut = p.units.reduce((t, u) => t + u.questions, 0);
    if (ut !== p.questions) console.log(`  ! ${e.code} ${p.key}: units sum ${ut} ≠ part ${p.questions}`);
  }
  console.log(`${e.code}: parts ${total}, units ${unitsTotal}, expected ${e.totalQuestions}`);
}
